-- German A1 educational audit fixes, 2026-09-18.
-- No German learner-facing text is authored or corrected here.
-- Five lessons are fully replaced with reusable source-backed German.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;
SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);

INSERT INTO sources(source_key,title,title_fa,organization_or_author,language_code,source_type,url,locator,locator_fa,published_or_updated_at,modernity_status,currency_evidence,license_name,license_url,attribution_text,reuse_status,retrieved_at,notes) VALUES
('src-wikibooks-de-weather-appendix','German/Appendices/Vocabulary/Weather','واژگان و عبارت‌های سادهٔ آب‌وهوا','Wikibooks contributors','de','website','https://en.wikibooks.org/wiki/German/Appendices/Vocabulary/Weather','Das Wetter: basic current-weather questions and simple condition phrases including sunny, rainy, cloudy and snow.','بخش آب‌وهوا؛ پرسش دربارهٔ هوای یک شهر و عبارت‌های سادهٔ آفتابی، بارانی، ابری و برفی.',NULL,'maintained_current','صفحهٔ زندهٔ واژگان آب‌وهوا در ویکی‌بوکس در ۱۸ سپتامبر ۲۰۲۶ بررسی شد. فقط پرسش‌های کوتاه و عبارت‌های سادهٔ وضعیت فعلی هوا که در نسخهٔ جاری صفحه حضور دارند برای A1 استفاده می‌شوند.','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Wikibooks contributors — German/Appendices/Vocabulary/Weather','reuse_with_attribution','2026-09-18','این منبع برای ساده‌سازی دو درس آب‌وهوا استفاده می‌شود تا ساختارهای سنگین‌تر پیش‌بینی و توصیه از مسیر تولیدی A1 حذف شوند.')
ON DUPLICATE KEY UPDATE title=VALUES(title),title_fa=VALUES(title_fa),organization_or_author=VALUES(organization_or_author),language_code=VALUES(language_code),source_type=VALUES(source_type),url=VALUES(url),locator=VALUES(locator),locator_fa=VALUES(locator_fa),modernity_status=VALUES(modernity_status),currency_evidence=VALUES(currency_evidence),license_name=VALUES(license_name),license_url=VALUES(license_url),attribution_text=VALUES(attribution_text),reuse_status=VALUES(reuse_status),retrieved_at=VALUES(retrieved_at),notes=VALUES(notes);
INSERT INTO sources(source_key,title,title_fa,organization_or_author,language_code,source_type,url,locator,locator_fa,published_or_updated_at,modernity_status,currency_evidence,license_name,license_url,attribution_text,reuse_status,retrieved_at,notes) VALUES
('src-wikibooks-de-transport-dialogue-current','Ungarisch: Themengebiete: Dialoge — Dialog 3','گفت‌وگوی کوتاه اتوبوس، قطار و سکو','Wikibooks contributors','de','website','https://de.wikibooks.org/wiki/Ungarisch:_Themengebiete:_Dialoge','Dialog 3: bus stop, next train, departure time and platform information.','گفت‌وگوی ۳؛ پرسش دربارهٔ توقف اتوبوس و زمان و سکوی قطار.',NULL,'maintained_current','صفحهٔ زندهٔ گفت‌وگوهای ویکی‌بوکس در ۱۸ سپتامبر ۲۰۲۶ بررسی شد. بخش انتخاب‌شده گفت‌وگوی کوتاه و معاصر دربارهٔ توقف اتوبوس، زمان حرکت قطار و شمارهٔ سکو دارد و برای A1 مناسب است.','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Wikibooks contributors — Ungarisch: Themengebiete: Dialoge — Dialog 3','reuse_with_attribution','2026-09-18','فقط جمله‌های آلمانی خودِ گفت‌وگوی ۳ دربارهٔ حمل‌ونقل استفاده می‌شوند؛ هیچ جملهٔ آلمانی تازه برای تکمیل گفت‌وگو ساخته نمی‌شود.')
