UPDATE lessons SET status='qa',title_fa='این برنامه براتون مناسبه؟',activity_selection_rationale='به‌جای دستکاری جملهٔ آلمانی مشکل‌دار قبلی، کل درس با نمونه‌های صحیح و عیناً منبع‌دارِ موافقت با برنامه جایگزین شده است.',sequence_rationale='مکالمه دو نمونهٔ موافقت را در بافت می‌آورد، سپس پاسخ مناسب انتخاب می‌شود و در پایان یک پاسخ کوتاه بازسازی می‌شود.',template_signature='conversation_speaking>choose_response>word_order',audio_status='stale',notes='بازبینی کامل ۱۸ سپتامبر ۲۰۲۶: کل درس بدون اصلاح دستی آلمانی با محتوای منبع‌دار جایگزین شد.' WHERE id=@lesson;
