INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-time-review-conversation',@lesson,1,'conversation_speaking','در دو برنامهٔ کوتاه، مناسب‌بودن پیشنهاد را بفهم و موافقت کن.','چهار نوبت عین بخش موافقت منبع هستند و خطای جملهٔ قبلی را بدون بازنویسی آلمانی حذف می‌کنند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-reschedule-exact-time' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"app"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required');
SET @act := (SELECT id FROM activities WHERE activity_key='act-de-a1-time-review-conversation' LIMIT 1);
