('act-de-a1-time-review-matching',@lesson,2,'choose_response','برای این پیشنهاد، پاسخ موافقت را انتخاب کن.','گزینهٔ درست و گزینه‌های دیگر همگی از نمونه‌های همان منبع انتخاب شده‌اند.',NULL,CAST('{"promptTarget":"Ich begleite Sie noch ein Stück. Ist Ihnen das recht?","promptFa":"کمی دیگر همراهتان می‌آیم. برایتان مناسب است؟","options":[{"textTarget":"Ja, ich bin einverstanden.","translationFa":"بله، موافقم.","correct":true},{"textTarget":"Es tut mir leid, heute geht es nicht.","translationFa":"متأسفم، امروز نمی‌شود.","correct":false},{"textTarget":"Morgen geht es vielleicht.","translationFa":"فردا شاید بشود.","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required');
