UPDATE lessons SET status='qa',title_fa='باران یا برف؟',activity_selection_rationale='عبارت‌های دماسنجِ مصنوعی درس قبلی کنار گذاشته شده‌اند؛ این درس کامل با دو وضعیت بسیار ساده و منبع‌دار باران و برف جایگزین شده است.',sequence_rationale='مکالمه دو وضعیت را معرفی می‌کند، سپس معنی باران تشخیص داده می‌شود و در پایان عبارت برف بازسازی می‌شود.',template_signature='conversation_speaking>multiple_choice>word_order',audio_status='stale',notes='بازبینی کامل ۱۸ سپتامبر ۲۰۲۶: کل درس بدون اصلاح دستی آلمانی با محتوای منبع‌دار جایگزین شد.' WHERE id=@lesson;
DELETE p FROM provenance_links p JOIN activities a ON p.entity_type='activity' AND p.entity_key=a.activity_key WHERE a.lesson_id=@lesson;
