UPDATE units SET title_fa='زمان، برنامه و قرار',grouping_rationale='واحد از فهم بازهٔ زمانی به دعوت و سپس موافقت یا رد یک برنامه می‌رسد. درس سوم پس از بازبینی کامل با نمونه‌های صحیح و عیناً منبع‌دارِ موافقت جایگزین شده است.',metadata=CAST('{"sourceRefs":["src-wikibooks-de-lesson-021-time-appointment"],"learningTargets":["بازهٔ زمانی یک برنامه را با ساعت شروع و پایان بفهمد.","پرسش و پاسخ دربارهٔ «تا چه زمانی» را در برنامهٔ روزمره بفهمد.","یک دعوت ساده و رد مؤدبانه را دنبال کند.","پرسش دربارهٔ مناسب‌بودن یک برنامه را بفهمد و پاسخ موافقت را تشخیص دهد."]}' AS JSON),notes='هیچ متن آلمانی این واحد برای اصلاح دستی بازنویسی نمی‌شود؛ در بازبینی ۱۸ سپتامبر ۲۰۲۶ درس سوم به‌طور کامل با محتوای منبع‌دار جایگزین شد.' WHERE unit_key='de-a1-unit-time-plans-appointment' AND language_level_id=@level;
UPDATE units SET title_fa='مسیر و مکان‌های عمومی',grouping_rationale='واحد روی سه نیاز مکانی متمرکز است: پیدا کردن هتل و رستوران، پرسیدن و دنبال‌کردن مسیر شهری، و پرسیدن مسیر ایستگاه یا فرودگاه. موضوع زمان قطار از این واحد حذف شده تا با واحد حمل‌ونقل هم‌پوشانی نداشته باشد.',metadata=CAST('{"sourceRefs":["src-wikibooks-german-print-directions","src-wikivoyage-german-phrasebook-directions","src-wikibooks-de-lesson-006-where-when"],"learningTargets":["برای رسیدن به یک مکان عمومی مسیر را به شکل ساده بپرسد.","راهنمایی کوتاه با راست، چپ و مستقیم را بفهمد.","مسیر مکان‌هایی مانند ایستگاه قطار و فرودگاه را در پرسش‌های بسیار ساده دنبال کند."]}' AS JSON),notes='درس سوم در بازبینی ۱۸ سپتامبر ۲۰۲۶ به‌طور کامل با محتوای مسیرِ منبع‌دار جایگزین شد و دیگر از نمونهٔ زمان رسیدن قطار استفاده نمی‌کند.' WHERE unit_key='de-a1-unit-directions-public-places' AND language_level_id=@level;
UPDATE units SET title_fa='بلیت و حمل‌ونقل عمومی',grouping_rationale='واحد سه گام مستقل سفر با حمل‌ونقل عمومی را پوشش می‌دهد: درخواست بلیت، تشخیص وسیله یا توقف درست، و فهم اطلاعات واقعیِ زمان و سکو.',metadata=CAST('{"sourceRefs":["src-wikivoyage-german-phrasebook-transport","src-wikivoyage-german-phrasebook-directions","src-wikibooks-de-transport-dialogue-current"],"learningTargets":["برای یک مقصد ساده بلیت بخواهد.","قطار یا اتوبوس درست را با پرسش دربارهٔ مقصد و توقف تشخیص دهد.","اطلاعات سادهٔ توقف، زمان حرکت و شمارهٔ سکو را در یک گفت‌وگوی کوتاه بفهمد."]}' AS JSON),notes='در بازبینی ۱۸ سپتامبر ۲۰۲۶ ادعای آموزش قیمت بلیت حذف شد و درس سوم با گفت‌وگوی منبع‌دارِ واقعی دربارهٔ توقف، زمان و سکو جایگزین شد.' WHERE unit_key='de-a1-unit-public-transport-tickets' AND language_level_id=@level;
UPDATE units SET title_fa='آب‌وهوا',grouping_rationale='واحد از پرسش دربارهٔ هوای فعلی به تشخیص وضعیت‌های بسیار سادهٔ آفتابی، ابری، بارانی و برفی می‌رود. دو درس سنگین‌تر قبلی در بازبینی کامل با محتوای ساده‌تر و عیناً منبع‌دار جایگزین شدند.',metadata=CAST('{"sourceRefs":["src-wikibooks-german-print-weather","src-wikibooks-de-weather-appendix"],"learningTargets":["دربارهٔ هوای فعلی یک شهر سؤال کند و پاسخ ساده را بفهمد.","وضعیت‌های سادهٔ آفتابی و ابری را در پاسخ کوتاه تشخیص دهد.","وضعیت‌های سادهٔ باران و برف را از هم تشخیص دهد."]}' AS JSON),notes='واژگان تخصصی، ساختارهای سنگین توصیه و عبارت‌های مصنوعی دماسنج از مسیر تولیدی این واحد حذف شده‌اند.' WHERE unit_key='de-a1-unit-weather-temperature' AND language_level_id=@level;
UPDATE units SET title_fa='سلامت، پزشک و داروخانه',grouping_rationale='واحد از بیان مستقیم علامت شروع می‌کند، سپس دارو و داروخانه را پوشش می‌دهد و در پایان به پیگیری حال بیمار و بیان بهترشدن می‌رسد.',metadata=CAST('{"sourceRefs":["src-wikibooks-de-lesson-018-health"],"learningTargets":["علائم بسیار رایج بیماری را در پرسش و پاسخ کوتاه بیان و تشخیص دهد.","دارو و محل گرفتن دارو را در یک موقعیت سادهٔ پزشکی بفهمد.","با الگوی سادهٔ «دیگر ندارم» بهترشدن یک علامت را بیان کند."]}' AS JSON),notes='ادعای آموزش نسخه در بازبینی ۱۸ سپتامبر ۲۰۲۶ حذف شد، چون فعالیت‌های فعلی این واحد نسخه را به‌صورت مستقیم آموزش نمی‌دهند.' WHERE unit_key='de-a1-unit-health-doctor-pharmacy' AND language_level_id=@level;
UPDATE language_levels SET
notes='A1 شامل ۱۳ واحد و ۳۹ درس است. در بازبینی کامل ۱۸ سپتامبر ۲۰۲۶، پنج درس دارای خطای واقعی، هم‌پوشانی یا سطح نامناسب بدون اصلاح دستی متن آلمانی به‌طور کامل با محتوای عیناً منبع‌دار جایگزین شدند. وضعیت صوتی پس از هر تغییر محتوای نمایش‌داده‌شونده به زبان‌آموز باید از فرایند صوت مرجع دوباره محاسبه شود.',
audio_status='stale',
coverage=JSON_SET(coverage,
  '$.communicativeTargets[16]','گرفتن بلیت و فهم اطلاعات بسیار سادهٔ حمل‌ونقل عمومی، توقف، زمان و سکو',
  '$.communicativeTargets[17]','پرسیدن و فهم هوای فعلی و وضعیت‌های سادهٔ آفتابی، ابری، بارانی و برفی',
  '$.linguisticTargets[11]','خواندن و تلفظ واضح حروف، واژه‌ها و جمله‌های کوتاه در حد فعالیت‌های منبع‌دار موجود',
  '$.situations[11]','بلیت، قطار، اتوبوس، توقف و سکو',
  '$.situations[12]','آب‌وهوا، آفتاب، ابر، باران و برف')
WHERE id=@level;

COMMIT;
